  function unavailable(){halt();chosen=null;items=[];choices.replaceChildren();timeline.replaceChildren();play.disabled=true;status.textContent='Historique indisponible ou périmé. Aucune reconstitution inventée.';}
  async function refreshReplays(){if(document.hidden)return;try{const data=await api('/api/public/replays');const now=Date.now()/1000;if(data.available!==true||!Number.isFinite(data.observed_at)||data.observed_at<now-90||data.observed_at>now+10||!Array.isArray(data.replays)){unavailable();return;}replayExpiry=data.observed_at*1000+90000;const clean=data.replays.slice(0,20).filter(r=>r&&typeof r.ref==='string'&&r.ref.length<=200&&Object.hasOwn(states,r.status)&&Array.isArray(r.events)).map(r=>({ref:r.ref,role:roles.some(x=>x.id===r.role)?r.role:null,status:r.status,events:r.events.slice(0,3).filter(e=>e&&Object.hasOwn(kinds,e.kind)&&Number.isFinite(e.at)&&e.at>0&&e.at<=now+10).sort((a,b)=>a.at-b.at)}));if(JSON.stringify(clean)===JSON.stringify(items))return;halt();items=clean;choices.replaceChildren();clean.forEach((item,i)=>{const b=el('button','','Tâche '+(i+1)+' · '+replayRole(item.role)+' · '+states[item.status]);b.type='button';b.addEventListener('click',()=>choose(item,i));choices.append(b);});if(clean.length)choose(clean[0],0);else{chosen=null;play.disabled=true;timeline.replaceChildren();status.textContent='Aucune tâche anonymisée disponible dans cette observation.';}}catch{unavailable();}}
  play.addEventListener('click',()=>{if(!chosen||!chosen.events.length)return;if(playing){halt();status.textContent='Relecture en pause. Les dates restent consultables.';return;}if(document.body.classList.contains('paused')){status.textContent='Reprenez les animations avec le bouton en haut de page, puis relancez la lecture.';return;}if(cursor>=chosen.events.length)cursor=0;playing=true;finishUntil=0;play.textContent='Pause';nextAt=0;resetScene();});
  const scenes=[['Pause café','Une tasse de café ?','Avec plaisir, une petite pause !'],['Rangement','On remet ces crayons dans leur pot ?','Oui, et je range les feuilles.'],['Pause','On s’étire un peu ?','Bonne idée, les ailes aussi !'],['Accueil','Bienvenue dans notre petit bureau.','Entrez, il y a une place ici.'],['Café','Thé ou café pour la pause ?','Un thé, merci !'],['Coin lecture','Tu me passes ce carnet vide ?','Le voici, tout neuf.']];
  function shuffle(values){for(let i=values.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[values[i],values[j]]=[values[j],values[i]];}return values;}
