 const office=document.getElementById('office'),stage=make('section',undefined,'trace-stage'),speech=make('div',undefined,'trace-stage-speech'),speaker=make('strong'),body=make('p'),badge=make('span','Résumé vérifié — pas verbatim','trace-stage-badge'),toolBadge=make('span',undefined,'trace-stage-tool'),stageControls=make('div',undefined,'trace-stage-controls'),progress=make('span','0 / 0'),previous=make('button','←'),following=make('button','→'),toggle=make('button','Lire'),again=make('button','Rejouer'),leave=make('button','Quitter'),mode=make('select'),stageSpeed=speed.cloneNode(true),neutrals=make('div',undefined,'trace-neutrals');
 stage.hidden=true;stage.setAttribute('aria-label','Mise en scène du journal');body.setAttribute('aria-live','polite');speech.append(badge,speaker,toolBadge,body);stage.append(speech,stageControls);office.append(neutrals,stage);
