 setInterval(()=>{if(!allowed()){if(items.length)clear('Connexion privée requise.');return;}if(items.length&&Date.now()>expires){clear('Journal périmé ; actualisation nécessaire.');return;}if(!playing)return;if(document.hidden||document.body.classList.contains('paused')){pauseStage();return;}if(Date.now()<deadline)return;if(currentIndex+1<playbackSteps().length){paint(currentIndex+1,true);return;}pauseStage();ended=true;toggle.textContent='Relire';badge.textContent='Fin du déroulé — résultat limité aux preuves';body.textContent=chosen.story?.result||'Les événements seuls ne prouvent pas un succès vérifié.';if(chosen.story?.limitations)body.textContent+=' '+chosen.story.limitations;notice.textContent=body.textContent;},150);
